actionConfiguration.body:
function (start, dur, blocked, bks, now) {
  if (!(start instanceof Date) || isNaN(start)) return {
    code: "INVALID_START",
    msg: "Enter a valid start date and time."
  };
  if (!Number.isFinite(dur)) return {
    code: "INVALID_DURATION",
    msg: "Enter the duration as a number of minutes."
  };
  if (start <= now) return {
    code: "PAST_START",
    msg: "Start time must be in the future."
  };
  if (dur <= 0) return {
    code: "DURATION_TOO_SHORT",
    msg: "Duration must be greater than 0 minutes."
  };
  if (dur > 120) return {
    code: "DURATION_TOO_LONG",
    msg: "Duration cannot exceed 120 minutes."
  };
  if (blocked) return {
    code: "ROOM_BLOCKED",
    msg: "Unavailable: the room is blocked."
  };
  const end = new Date(start.getTime() + dur * 60000);
  const hit = bks.find(b => start < b.end && end > b.start);
  if (hit) return {
    code: "OVERLAP",
    msg: "Unavailable: overlaps with " + hit.title
  };
  return {
    code: "OK",
    msg: "Available for the selected time."
  };
}

