actionConfiguration.body:
function () {
  const bks = Checker.bookings(), snap = JSON.stringify(bks), now = new Date();
  const T = [["T1", "Free 11:30, 60", "OK", Checker.dayAt(1, 11, 30), 60, false], ["T2", "Overlap 10:30, 60", "OVERLAP", Checker.dayAt(1, 10, 30), 60, false], ["T3", "Blocked 15:00", "ROOM_BLOCKED", Checker.dayAt(1, 15, 0), 60, true], ["T4", "Duration 0", "DURATION_TOO_SHORT", Checker.dayAt(1, 15, 0), 0, false], ["T5", "Duration 121", "DURATION_TOO_LONG", Checker.dayAt(1, 15, 0), 121, false], ["T6", "Past start", "PAST_START", Checker.dayAt(-1, 10, 0), 60, false], ["T7", "Adjacent 11:00, 60", "OK", Checker.dayAt(1, 11, 0), 60, false]];
  const rows = T.map(([id, c, exp, s, d, bl]) => {
    const obs = Checker.check(s, d, bl, bks, now).code;
    return {
      ID: id,
      Case: c,
      Expected: exp,
      Observed: obs,
      Result: obs === exp ? "PASS" : "FAIL"
    };
  });
  const same = JSON.stringify(bks) === snap;
  rows.push({
    ID: "T8",
    Case: "Bookings unchanged",
    Expected: "Unchanged",
    Observed: same ? "Unchanged" : "Changed",
    Result: same ? "PASS" : "FAIL"
  });
  return rows;
}

