export default {
  dayAt(offset, h, m) {
    const d = new Date();
    d.setDate(d.getDate() + offset);
    d.setHours(h, m, 0, 0);
    return d;
  },
  bookings() {
    return [
      { title: "Algorithms seminar", start: this.dayAt(1,10,0), end: this.dayAt(1,11,0) },
      { title: "Study group",        start: this.dayAt(1,13,0), end: this.dayAt(1,14,30) }
    ];
  },
  check(start, dur, blocked, bks, now) {
    if (!(start instanceof Date) || isNaN(start)) return { code: "INVALID_START", msg: "Enter a valid start date and time." };
    if (!Number.isFinite(dur)) return { code: "INVALID_DURATION", msg: "Enter the duration as a number of minutes." };
    if (start <= now) return { code: "PAST_START", msg: "Start time must be in the future." };
    if (dur <= 0) return { code: "DURATION_TOO_SHORT", msg: "Duration must be greater than 0 minutes." };
    if (dur > 120) return { code: "DURATION_TOO_LONG", msg: "Duration cannot exceed 120 minutes." };
    if (blocked) return { code: "ROOM_BLOCKED", msg: "Unavailable: the room is blocked." };
    const end = new Date(start.getTime() + dur * 60000);
    const hit = bks.find(b => start < b.end && end > b.start);
    if (hit) return { code: "OVERLAP", msg: "Unavailable: overlaps with " + hit.title };
    return { code: "OK", msg: "Available for the selected time." };
  },
  run() {
    const dur = DurInput.text === "" ? NaN : Number(DurInput.text);
    const r = this.check(new Date(StartInput.selectedDate), dur, BlockedSwitch.isSwitchedOn, this.bookings(), new Date());
    storeValue("result", r.msg + " [" + r.code + "]");
  },
  runTests() {
    const bks = this.bookings(), snap = JSON.stringify(bks), now = new Date();
    const T = [
      ["T1","Free 11:30, 60","OK",         this.dayAt(1,11,30),60,false],
      ["T2","Overlap 10:30, 60","OVERLAP", this.dayAt(1,10,30),60,false],
      ["T3","Blocked 15:00","ROOM_BLOCKED",this.dayAt(1,15,0),60,true],
      ["T4","Duration 0","DURATION_TOO_SHORT",this.dayAt(1,15,0),0,false],
      ["T5","Duration 121","DURATION_TOO_LONG",this.dayAt(1,15,0),121,false],
      ["T6","Past start","PAST_START",    this.dayAt(-1,10,0),60,false],
      ["T7","Adjacent 11:00, 60","OK",     this.dayAt(1,11,0),60,false]
    ];
    const rows = T.map(([id,c,exp,s,d,bl]) => {
      const obs = this.check(s,d,bl,bks,now).code;
      return { ID:id, Case:c, Expected:exp, Observed:obs, Result: obs===exp ? "PASS":"FAIL" };
    });
    const same = JSON.stringify(bks) === snap;
    rows.push({ ID:"T8", Case:"Bookings unchanged", Expected:"Unchanged", Observed: same?"Unchanged":"Changed", Result: same?"PASS":"FAIL" });
    return rows;
  }
}
